import {sphere,unit} from './atmosphere.mjs';
function cloudHash(x,z,seed){let h=Math.imul(x,73856093)^Math.imul(z,19349663)^(seed>>>0);h^=h>>>13;return (Math.imul(h,1274126177)>>>0)/4294967295;}
function cloudNoise(x,z,seed){const ix=Math.floor(x),iz=Math.floor(z),fx=x-ix,fz=z-iz,sx=fx*fx*(3-2*fx),sz=fz*fz*(3-2*fz),a=cloudHash(ix,iz,seed),b=cloudHash(ix+1,iz,seed),c=cloudHash(ix,iz+1,seed),d=cloudHash(ix+1,iz+1,seed);return (a*(1-sx)+b*sx)*(1-sz)+(c*(1-sx)+d*sx)*sz;}
export function cloudDensity(normal,seed,time){const n=unit(normal),phase=(seed%65536)/65536*Math.PI*2,cx=.03*Math.sin(phase),cz=.03*Math.cos(phase);const storm=.7*Math.exp(-((n[0]-cx)**2+(n[2]-cz)**2)/.04),detail=.25*Math.sin(n[0]*15+n[2]*11+phase+time*.015)*Math.sin(n[2]*21-n[0]*13+phase*1.7)+.08*Math.sin(n[0]*35+n[2]*39+phase*.4);const blend=Math.max(0,Math.min(1,(n[1]-.985)/.01)),polar=blend*blend*(3-2*blend),breaks=polar*.16*(cloudNoise(n[0]*120+time*.015,n[2]*120-time*.009,seed)-.5),opening=polar*.8*Math.exp(-(n[0]**2+(n[2]-.00052)**2)/.000004);return Math.max(0,Math.min(1,(storm+detail+breaks-opening-.35)/.55));}
// A bounded spherical medium, clipped by the visible solid surface.
export function cloudInterval(eye,direction,radius,height,thickness,distance){const d=unit(direction),outer=sphere(eye,d,radius+height+thickness/2),inner=sphere(eye,d,radius+height-thickness/2);if(!outer)return null;let near=Math.max(0,outer.near),far=Math.min(distance,outer.far);if(inner){if(Math.hypot(...eye)<radius+height-thickness/2)near=Math.max(near,inner.far);else if(inner.near>=0)far=Math.min(far,inner.near);}return far>near?{near,far}:null;}
